import { createSanityInstance, type SanityInstance } from "@sanity/sdk";
import { defer, EMPTY, filter, from, map, type Observable } from "rxjs";
import {
  type ActorRefFrom,
  raise,
  sendTo,
  setup,
  type ActorOptions,
} from "xstate";

import type { LocalApplication } from "../core/applications/applications";
import type { LocalAppConfig } from "../core/installations/config";
import { logger } from "../core/log";
import { brandOrganizationId } from "../core/organizations";
// Aliased because this module exports the OS machine as `os`.
import { os as bus } from "../runtime/bus";
import { applicationsLogic } from "./applications/machine";
import { authLogic } from "./auth.machine";
import { inspect } from "./inspect";
import {
  createInstance,
  type FederationInstance,
  log,
} from "./module-federation";
import { organizationLogic } from "./organization.machine";
import { panelsLogic } from "./panels.machine";
import { projectsLogic } from "./projects.machine";
import { remotesLogic } from "./remotes.machine";
import { servicesLogic } from "./services.machine";
import {
  type SystemPreferencesAdapter,
  systemPreferencesLogic,
} from "./system-preferences.machine";
import {
  telemetryLogic,
  type WorkbenchUserProperties,
} from "./telemetry.machine";

type OSInput = WorkbenchUserProperties & {
  systemPreferencesAdapter?: SystemPreferencesAdapter;
  /**
   * Apps served by attached dev servers. A stream, so the applications machine
   * can subscribe directly and a dev server coming or going rebuilds the list
   * without a host re-render.
   */
  localApplications?: Observable<LocalApplication[]>;
  appConfigs?: Observable<LocalAppConfig[]>;
};

type OSContext = {
  instance: SanityInstance;
  /**
   * The single module-federation instance every interface loads through —
   * shared by the `remotes` (views) and `services` (workers) supervisors so an
   * app's remote is registered once for all its interfaces.
   */
  federationInstance: FederationInstance;
  userProperties: WorkbenchUserProperties;
  systemPreferencesAdapter: SystemPreferencesAdapter | undefined;
  localApplications: Observable<LocalApplication[]>;
  appConfigs: Observable<LocalAppConfig[]>;
};

/**
 * The base inputs for the OS machine.
 * @internal
 */
export interface OSBaseInput extends Pick<OSContext, "instance"> {}

/**
 * The sanity OS machine, responsible for managing the global state of the OS.
 * @public
 * @example
 * ```ts
 * import { os, createOSOptions } from "@sanity/workbench/system";
 * import { useActor } from "@xstate/react";
 *
 * const [state, send] = useActor(os, createOSOptions({
 *   version: "1.0.0",
 *   organizationId: "...",
 *   environment: "production",
 *   userAgent: navigator.userAgent,
 * }));
 * ```
 */
export const os = setup({
  types: {
    input: {} as OSInput,
    context: {} as OSContext,
    events: {} as
      | { type: "boot.auth.ready" }
      | { type: "boot.auth.failed" }
      | { type: "boot.organization.ready" }
      | { type: "boot.organization.failed" },
    // https://github.com/statelyai/xstate/issues/5515
    children: {} as {
      applications: "applications";
      auth: "auth";
      organization: "organization";
      panels: "panels";
      projects: "projects";
      telemetry: "telemetry";
      "system-preferences": "systemPreferences";
      remotes: "remotes";
      services: "services";
    },
  },
  actors: {
    applications: applicationsLogic,
    auth: authLogic,
    organization: organizationLogic,
    panels: panelsLogic,
    projects: projectsLogic,
    telemetry: telemetryLogic,
    systemPreferences: systemPreferencesLogic,
    remotes: remotesLogic,
    services: servicesLogic,
  },
  guards: {
    hasTag: (_, params: { hasTag: boolean }) => params.hasTag,
  },
  actions: {
    raiseAuthReady: raise({ type: "boot.auth.ready" }),
    raiseAuthFailed: raise({ type: "boot.auth.failed" }),
    raiseOrganizationReady: raise({ type: "boot.organization.ready" }),
    raiseOrganizationFailed: raise({ type: "boot.organization.failed" }),
    startTelemetry: sendTo("telemetry", {
      type: "telemetry.start",
    }),
    clearSession: () => {
      bus.emit("organizations.current", null);
      bus.emit("applications.foreground", null);
      bus.emit("applications.list", null);
      bus.emit("media-libraries.config", null);
      bus.emit("panels.mode", null);
    },
  },
}).createMachine({
  id: "os",
  context: ({ input }) => ({
    instance: createSanityInstance(),
    federationInstance: createInstance({
      name: "workbench-applications",
      plugins: [log(logger.debug)],
    }),
    userProperties: {
      version: input.version,
      organizationId: input.organizationId,
      environment: input.environment,
      userAgent: input.userAgent,
    },
    systemPreferencesAdapter: input.systemPreferencesAdapter,
    localApplications: input.localApplications ?? EMPTY,
    appConfigs: input.appConfigs ?? EMPTY,
  }),
  initial: "booting",
  invoke: [
    {
      id: "auth",
      systemId: "auth",
      src: "auth",
      input: ({ context }) => ({ instance: context.instance }),
      onSnapshot: [
        // LoginRedirect hard-navigates on LOGGED_OUT, disposing this actor, so
        // the OS intentionally has no signed-out transition of its own.
        {
          guard: {
            type: "hasTag",
            params: ({ event }) => ({
              hasTag: event.snapshot.hasTag("authenticated"),
            }),
          },
          actions: [{ type: "raiseAuthReady" }],
        },
        {
          guard: {
            type: "hasTag",
            params: ({ event }) => ({
              hasTag: event.snapshot.hasTag("error"),
            }),
          },
          actions: [{ type: "raiseAuthFailed" }],
        },
      ],
    },
    {
      id: "system-preferences",
      systemId: "system-preferences",
      src: "systemPreferences",
      input: ({ context }) => ({ adapter: context.systemPreferencesAdapter }),
    },
    {
      id: "remotes",
      systemId: "remotes",
      src: "remotes",
      input: ({ context }) => ({ instance: context.federationInstance }),
    },
    {
      id: "services",
      systemId: "services",
      src: "services",
      input: ({ context }) => ({ instance: context.federationInstance }),
    },
  ],
  states: {
    booting: {
      on: {
        "boot.auth.ready": { target: "running" },
        "boot.auth.failed": { target: "error" },
      },
    },
    // Authentication makes the shell renderable. These actors continue their
    // own loading work while the shell renders its skeletons.
    running: {
      exit: [{ type: "clearSession" }],
      invoke: [
        {
          id: "organization",
          systemId: "organization",
          src: "organization",
          input: ({ context }) => ({
            instance: context.instance,
            organizationId: context.userProperties.organizationId,
          }),
          onSnapshot: [
            {
              guard: {
                type: "hasTag",
                params: ({ event }) => ({
                  hasTag: event.snapshot.hasTag("organization-resolved"),
                }),
              },
              actions: [{ type: "raiseOrganizationReady" }],
            },
            {
              guard: {
                type: "hasTag",
                params: ({ event }) => ({
                  hasTag: event.snapshot.hasTag("error"),
                }),
              },
              actions: [{ type: "raiseOrganizationFailed" }],
            },
          ],
        },
        {
          id: "telemetry",
          systemId: "telemetry",
          src: "telemetry",
          input: ({ context }) => ({
            instance: context.instance,
            ...context.userProperties,
          }),
        },
        {
          id: "projects",
          systemId: "projects",
          src: "projects",
          input: ({ context }) => ({
            instance: context.instance,
            organizationId: brandOrganizationId(
              context.userProperties.organizationId,
            ),
          }),
        },
        {
          id: "applications",
          systemId: "applications",
          src: "applications",
          input: ({ context, self }) => ({
            instance: context.instance,
            // Host config supplies a plain string; the stores key on the brand.
            organizationId: brandOrganizationId(
              context.userProperties.organizationId,
            ),
            localApplications: context.localApplications,
            appConfigs: context.appConfigs,
            // Resolved at subscribe time, so this works whatever order the root
            // invokes its children in.
            projects: defer(() =>
              from(
                self.system.get("projects") as ActorRefFrom<
                  typeof projectsLogic
                >,
              ).pipe(
                map((snapshot) => snapshot.context.projects),
                filter((list) => list !== undefined),
              ),
            ),
          }),
        },
        {
          id: "panels",
          systemId: "panels",
          src: "panels",
        },
      ],
      on: {
        "boot.organization.ready": {
          actions: [{ type: "startTelemetry" }],
        },
        "boot.organization.failed": { target: "error" },
      },
    },
    error: {},
  },
});

/**
 * Creates a set of default options for the OS machine. Forwards the workbench
 * user properties to the machine's input and wires the structured-logging
 * `inspect` callback. Browser-specific concerns (color-scheme seeding,
 * persistence) live in the {@link SystemPreferencesAdapter} the host passes
 * via `systemPreferencesAdapter`.
 * @public
 */
export function createOSOptions(input: OSInput) {
  return {
    id: "os",
    input,
    inspect,
  } satisfies ActorOptions<typeof os>;
}
